  CreatedByUserID: string;
  /** Optional human-readable label for audit & management UI. */
  Label?: string;
  /** ISO 8601 expiration timestamp. */
  ExpiresAt: string;
  /** True when explicitly revoked prior to expiration. */
  Revoked?: boolean;
  /** ISO 8601 revocation timestamp. */
  RevokedAt?: string;
