    Samples?: number;
    Mode?: ''SinglePass'' | ''PerCriterion'';
    /** DecisionThenLLM: the decision prompt for its decision pass. Default `Default Decision`. PromptID/PromptName stay the LLM judge. */
    DecisionPromptID?: string;
