{% endif %}{% if Criterion.Description %}
{{ Criterion.Description | safe }}
{% endif %}{% if Criterion.Guidance %}
Guidance: {{ Criterion.Guidance | safe }}
{% endif %}{% if Criterion.Hints %}
Hints: {{ Criterion.Hints | safe }}
