SET
  @ID_508e8c95d713 = 'D534413A-310D-4ECF-A749-482A886B9EC6' EXEC [${flyway:defaultSchema}].spUpdateTemplateContent @TemplateText = @TemplateText_508e8c95d713,
  @ID = @ID_508e8c95d713;

-- Save MJ: AI Prompts (core SP call only)
