-- Save MJ: Query SQLs (core SP call only)
DECLARE @SQL_6299c0ab0f76 NVARCHAR(MAX),
@ID_6299c0ab0f76 UNIQUEIDENTIFIER
SET
  @SQL_6299c0ab0f76 = N'-- PostgreSQL variant: Get Conversation Artifacts For Agent
-- Mirrors get-conversation-artifacts-for-agent.sql for PG. Differences:
--   * `[${flyway:defaultSchema}].[X]` → `${flyway:defaultSchema}."X"` (schema brackets removed, view names quoted).
--   * Bare PascalCase column refs double-quoted to survive PG''s case-folding.

WITH RECURSIVE "ReadableCollections" AS (
    SELECT c."ID", 0 AS "Depth"
    FROM ${flyway:defaultSchema}."vwCollections" c
    WHERE c."OwnerID" = {{ Context.UserID | sqlString }}
       OR EXISTS (
           SELECT 1
           FROM ${flyway:defaultSchema}."vwCollectionPermissions" cp
           WHERE cp."CollectionID" = c."ID"
             AND cp."UserID" = {{ Context.UserID | sqlString }}
             AND (cp."CanRead" = true OR cp."CanEdit" = true OR cp."CanDelete" = true OR cp."CanShare" = true)
       )

    UNION ALL

    SELECT child."ID", rc."Depth" + 1 AS "Depth"
    FROM ${flyway:defaultSchema}."vwCollections" child
    INNER JOIN "ReadableCollections" rc ON child."ParentID" = rc."ID"
    WHERE rc."Depth" < 15
),
"ReadableArtifacts" AS (
    SELECT a_root."ID", 0 AS "Depth"
    FROM ${flyway:defaultSchema}."vwArtifacts" a_root
    WHERE (a_root."DelegateEntityID" IS NULL OR a_root."DelegateRecordID" IS NULL)
      AND (
          a_root."UserID" = {{ Context.UserID | sqlString }}
          OR EXISTS (
              SELECT 1
              FROM ${flyway:defaultSchema}."vwArtifactPermissions" ap
              WHERE ap."ArtifactID" = a_root."ID"
                AND ap."UserID" = {{ Context.UserID | sqlString }}
                AND (ap."CanRead" = true OR ap."CanEdit" = true OR ap."CanDelete" = true OR ap."CanShare" = true)
          )
          OR EXISTS (
              SELECT 1
              FROM ${flyway:defaultSchema}."vwCollectionArtifacts" ca
              INNER JOIN ${flyway:defaultSchema}."vwArtifactVersions" av_ca ON ca."ArtifactVersionID" = av_ca."ID"
              INNER JOIN "ReadableCollections" rc ON ca."CollectionID" = rc."ID"
              WHERE av_ca."ArtifactID" = a_root."ID"
          )
      )

    UNION ALL

    SELECT child_art."ID", ra."Depth" + 1 AS "Depth"
    FROM ${flyway:defaultSchema}."vwArtifacts" child_art
    INNER JOIN ${flyway:defaultSchema}."vwEntities" e_del ON child_art."DelegateEntityID" = e_del."ID" AND e_del."Name" = ''MJ: Artifacts''
    INNER JOIN "ReadableArtifacts" ra ON LOWER(ra."ID"::text) = LOWER(child_art."DelegateRecordID")
    WHERE ra."Depth" < 8
      AND child_art."DelegateRecordID" IS NOT NULL
)
SELECT
    -- Artifact fields
    a."ID" AS "ArtifactID",
    a."Name" AS "ArtifactName",
    a."Description" AS "ArtifactDescription",
    a."Type" AS "ArtifactType",
    a."Visibility" AS "SharingScope",
    a."Comments" AS "ArtifactComments",
    a."__mj_CreatedAt" AS "ArtifactCreatedAt",
    a."__mj_UpdatedAt" AS "ArtifactUpdatedAt",

    -- Artifact Type details
    at."ID" AS "ArtifactTypeID",
    at."Name" AS "ArtifactTypeName",
    at."Description" AS "ArtifactTypeDescription",
    at."ContentType" AS "ArtifactTypeContentType",
    at."__mj_CreatedAt" AS "ArtifactTypeCreatedAt",
    at."__mj_UpdatedAt" AS "ArtifactTypeUpdatedAt",

    -- Version fields
    av."ID" AS "VersionID",
    av."VersionNumber" AS "Version",
    av."Configuration",
    av."Content",
    av."Comments" AS "VersionComments",
    av."__mj_CreatedAt" AS "VersionCreatedAt",
    av."__mj_UpdatedAt" AS "VersionUpdatedAt",

    -- ConversationDetailID that created this version (from join table)
    cda."ConversationDetailID"

FROM ${flyway:defaultSchema}."vwConversationDetailArtifacts" cda
INNER JOIN ${flyway:defaultSchema}."vwArtifactVersions" av ON cda."ArtifactVersionID" = av."ID"
INNER JOIN ${flyway:defaultSchema}."vwArtifacts" a ON av."ArtifactID" = a."ID"
INNER JOIN ${flyway:defaultSchema}."vwArtifactTypes" at ON a."TypeID" = at."ID"
INNER JOIN ${flyway:defaultSchema}."vwConversationDetails" cd ON cda."ConversationDetailID" = cd."ID"
INNER JOIN ${flyway:defaultSchema}."vwConversations" conv ON cd."ConversationID" = conv."ID"

WHERE cd."ConversationID" = {{ ConversationID | sqlString }}
  AND cda."Direction" = ''Output''  -- Only artifacts produced by agents (not inputs)
  AND (
      conv."UserID" = {{ Context.UserID | sqlString }}
      OR (
          conv."AnchorType" IS NOT NULL
          AND (
              EXISTS (
                  SELECT 1
                  FROM ${flyway:defaultSchema}."vwEntities" e_art_acl
                  INNER JOIN "ReadableArtifacts" ra_conv ON LOWER(ra_conv."ID"::text) = LOWER(conv."LinkedRecordID")
                  WHERE e_art_acl."ID" = conv."LinkedEntityID"
                    AND e_art_acl."Name" = ''MJ: Artifacts''
              )
              OR EXISTS (
                  SELECT 1
                  FROM ${flyway:defaultSchema}."vwEntities" e_col_acl
                  INNER JOIN "ReadableCollections" rc_conv ON LOWER(rc_conv."ID"::text) = LOWER(conv."LinkedRecordID")
                  WHERE e_col_acl."ID" = conv."LinkedEntityID"
                    AND e_col_acl."Name" = ''MJ: Collections''
              )
          )
      )
  )
  AND EXISTS (
      SELECT 1
      FROM "ReadableArtifacts" ra
      WHERE ra."ID" = a."ID"
  )
  {% if AgentID %}
  AND cd."AgentID" = {{ AgentID | sqlString }}  -- Optional: filter by specific agent ID
  {% endif %}

ORDER BY a."__mj_CreatedAt" ASC, av."VersionNumber" ASC
'
SET
  @ID_6299c0ab0f76 = '2C658D35-AD53-453C-A52A-57DDB7A036B6' EXEC [${flyway:defaultSchema}].spUpdateQuerySQL @SQL = @SQL_6299c0ab0f76,
  @ID = @ID_6299c0ab0f76;

-- Save MJ: Queries (core SP call only)
DECLARE @SQL_d9939b547ac6 NVARCHAR(MAX),
@ExtractedSQLHash_d9939b547ac6 NVARCHAR(64),
@ID_d9939b547ac6 UNIQUEIDENTIFIER
SET
  @SQL_d9939b547ac6 = N'-- Get Conversation Artifacts Map - Optimized for quick display with lazy loading
-- Returns basic artifact info for a conversation without loading full content
-- This query is optimized for performance by:
--   1. Using JOINs instead of separate queries
--   2. Excluding the Content field to reduce payload size
--   3. Filtering server-side for efficiency
-- Security note: Anchored conversations require non-SQL-scoped Artifacts/Collections anchors (`vwEntities`)
-- rather than evaluating TypeScript FieldSecuritySQLGate restrictedFields per anchor entity.
WITH ReadableCollections AS (
    SELECT c.ID, 0 AS Depth
    FROM [${flyway:defaultSchema}].[vwCollections] c
    WHERE c.OwnerID = {{ Context.UserID | sqlString }}
       OR EXISTS (
           SELECT 1
           FROM [${flyway:defaultSchema}].[vwCollectionPermissions] cp
           WHERE cp.CollectionID = c.ID
             AND cp.UserID = {{ Context.UserID | sqlString }}
             AND (cp.CanRead = 1 OR cp.CanEdit = 1 OR cp.CanDelete = 1 OR cp.CanShare = 1)
       )

    UNION ALL

    SELECT child.ID, rc.Depth + 1 AS Depth
    FROM [${flyway:defaultSchema}].[vwCollections] child
    INNER JOIN ReadableCollections rc ON child.ParentID = rc.ID
    WHERE rc.Depth < 15
),
ReadableArtifacts AS (
    SELECT a_root.ID, 0 AS Depth
    FROM [${flyway:defaultSchema}].[vwArtifacts] a_root
    WHERE (a_root.DelegateEntityID IS NULL OR a_root.DelegateRecordID IS NULL)
      AND (
          a_root.UserID = {{ Context.UserID | sqlString }}
          OR EXISTS (
              SELECT 1
              FROM [${flyway:defaultSchema}].[vwArtifactPermissions] ap
              WHERE ap.ArtifactID = a_root.ID
                AND ap.UserID = {{ Context.UserID | sqlString }}
                AND (ap.CanRead = 1 OR ap.CanEdit = 1 OR ap.CanDelete = 1 OR ap.CanShare = 1)
          )
          OR EXISTS (
              SELECT 1
              FROM [${flyway:defaultSchema}].[vwCollectionArtifacts] ca
              INNER JOIN [${flyway:defaultSchema}].[vwArtifactVersions] av_ca ON ca.ArtifactVersionID = av_ca.ID
              INNER JOIN ReadableCollections rc ON ca.CollectionID = rc.ID
              WHERE av_ca.ArtifactID = a_root.ID
          )
      )

    UNION ALL

    SELECT child_art.ID, ra.Depth + 1 AS Depth
    FROM [${flyway:defaultSchema}].[vwArtifacts] child_art
    INNER JOIN [${flyway:defaultSchema}].[vwEntities] e_del ON child_art.DelegateEntityID = e_del.ID AND e_del.Name = ''MJ: Artifacts''
    INNER JOIN ReadableArtifacts ra ON LOWER(CAST(ra.ID AS NVARCHAR(36))) = LOWER(child_art.DelegateRecordID)
    WHERE ra.Depth < 8
      AND child_art.DelegateRecordID IS NOT NULL
)
SELECT
    cda.ConversationDetailID,
    cda.Direction,
    av.ID as ArtifactVersionID,
    av.VersionNumber,
    av.ArtifactID,
    a.Name as ArtifactName, 
    a.Type as ArtifactType, 
    a.Description as ArtifactDescription
FROM [${flyway:defaultSchema}].[vwConversationDetailArtifacts] cda
INNER JOIN [${flyway:defaultSchema}].[vwArtifactVersions] av ON cda.ArtifactVersionID = av.ID
INNER JOIN [${flyway:defaultSchema}].[vwArtifacts] a ON av.ArtifactID = a.ID
INNER JOIN [${flyway:defaultSchema}].[vwConversationDetails] cd ON cda.ConversationDetailID = cd.ID
INNER JOIN [${flyway:defaultSchema}].[vwConversations] conv ON cd.ConversationID = conv.ID
WHERE cd.ConversationID = {{ ConversationID | sqlString }}
  AND cda.Direction = ''Output''
  AND (
      conv.UserID = {{ Context.UserID | sqlString }}
      OR (
          conv.AnchorType IS NOT NULL
          AND (
              EXISTS (
                  SELECT 1
                  FROM [${flyway:defaultSchema}].[vwEntities] e_art_acl
                  INNER JOIN ReadableArtifacts ra_conv ON LOWER(CAST(ra_conv.ID AS NVARCHAR(36))) = LOWER(conv.LinkedRecordID)
                  WHERE e_art_acl.ID = conv.LinkedEntityID
                    AND e_art_acl.Name = ''MJ: Artifacts''
              )
              OR EXISTS (
                  SELECT 1
                  FROM [${flyway:defaultSchema}].[vwEntities] e_col_acl
                  INNER JOIN ReadableCollections rc_conv ON LOWER(CAST(rc_conv.ID AS NVARCHAR(36))) = LOWER(conv.LinkedRecordID)
                  WHERE e_col_acl.ID = conv.LinkedEntityID
                    AND e_col_acl.Name = ''MJ: Collections''
              )
          )
      )
  )
  AND EXISTS (
      SELECT 1
      FROM ReadableArtifacts ra
      WHERE ra.ID = a.ID
  )
ORDER BY cda.__mj_CreatedAt, av.VersionNumber
'
SET
  @ExtractedSQLHash_d9939b547ac6 = N'2420e120aa6337d881327e1dcd77c22d824ea67f20f386f1fa6adf9a9fa84b0f'
SET
  @ID_d9939b547ac6 = 'EE272535-9D1D-4E4B-8613-1332CB564501' EXEC [${flyway:defaultSchema}].spUpdateQuery @SQL = @SQL_d9939b547ac6,
  @ExtractedSQLHash = @ExtractedSQLHash_d9939b547ac6,
  @ID = @ID_d9939b547ac6;

