DECLARE @ID_51bf0d1bb5ea UNIQUEIDENTIFIER,
@QueryID_51bf0d1bb5ea UNIQUEIDENTIFIER,
@RoleID_51bf0d1bb5ea UNIQUEIDENTIFIER
SET
  @ID_51bf0d1bb5ea = '34B1946F-9B88-46B5-9AB0-71920B133A8E'
